const SHAPE = {
	filled_square:   { filled: true,  rx: 0    },
	filled_rounded:  { filled: true,  rx: 4    },
	filled_pill:     { filled: true,  rx: 17.5 },
	outline_square:  { filled: false, rx: 0    },
	outline_rounded: { filled: false, rx: 3.5  },
	outline_pill:    { filled: false, rx: 17   },
};

const RADIUS_SIDES = ['top_left', 'top_right', 'bottom_right', 'bottom_left'];
const BORDER_SIDES = ['top', 'right', 'bottom', 'left'];

const ButtonPresetComponent = ( props ) => {
	const { label, choices } = props.control.params;
	const api               = wp.customize;
	const reset             = __( 'Back to default', 'responsive' );

	const [selected, setSelected] = useState( () => props.control.setting.get() || '' );

	const controlId = props.control.id || '';
	const isSecondary = controlId.includes( 'secondary' );
	const radiusPrefix = isSecondary ? 'responsive_secondary_buttons_radius_' : 'responsive_buttons_radius_';
	const borderPrefix = isSecondary ? 'responsive_secondary_buttons_border_width_' : 'responsive_buttons_border_width_';
	const defaultBorderWidth = isSecondary ? 2 : 0;

	const applyPreset = ( presetKey ) => {
		const choice = choices[ presetKey ];
		if ( ! choice ) return;

		props.control.setting.set( presetKey );
		setSelected( presetKey );

		RADIUS_SIDES.forEach( ( side ) => {
			const s = api( `${ radiusPrefix }${ side }_radius` );
			if ( s ) s.set( choice.radius );
		} );

		BORDER_SIDES.forEach( ( side ) => {
			const s = api( `${ borderPrefix }${ side }_border` );
			if ( s ) s.set( choice.border_width );
		} );
	};

	const onReset = () => {
		props.control.setting.set( '' );
		setSelected( '' );

		RADIUS_SIDES.forEach( ( side ) => {
			const s = api( `${ radiusPrefix }${ side }_radius` );
			if ( s ) s.set( 0 );
		} );

		BORDER_SIDES.forEach( ( side ) => {
			const s = api( `${ borderPrefix }${ side }_border` );
			if ( s ) s.set( defaultBorderWidth );
		} );
	};

	return (
		<>
			<div className="responsive-button-presets-control-label">
				<span className="customize-control-title">{ label }</span>
				<div className="responsive-reset-slider">
					<button type="button" className="responsive-slider-reset-btn" title={ reset } onClick={ onReset }>
						<svg width="12" height="12" viewBox="0 0 12 13" fill="none" xmlns="http://www.w3.org/2000/svg">
							<path fillRule="evenodd" clipRule="evenodd" d="M1.10666 2.92609L1.28436 0.0619233L0.286278 0L0.0309617 4.11519L0 4.61423L0.49904 4.6452L4.61423 4.90051L4.67616 3.90243L1.74564 3.72061C2.67116 2.63852 4.05283 1.95167 5.59638 1.95167C8.38299 1.95167 10.642 4.19024 10.642 6.95167C10.642 9.71309 8.38299 11.9517 5.59638 11.9517C3.89414 11.9517 2.38879 11.1163 1.47498 9.83677L0.651103 10.4135C1.39211 11.453 2.44747 12.2321 3.66465 12.6381C4.88183 13.0442 6.19777 13.0561 7.42228 12.6723C8.64678 12.2885 9.71642 11.5288 10.4766 10.503C11.2368 9.47722 11.6481 8.23845 11.6511 6.96577C11.6541 5.69308 11.2487 4.45241 10.4934 3.42308C9.73808 2.39374 8.67206 1.62906 7.44939 1.23956C6.22671 0.850065 4.91073 0.855925 3.69164 1.2563C2.69519 1.58355 1.80567 2.16051 1.10666 2.92609Z" fill="#9CA3AF" />
						</svg>
					</button>
				</div>
			</div>
			<div className="customize-control-responsive-buttonpreset">
				{ Object.keys( choices ).map( ( key ) => {
					const shape = SHAPE[ key ];
					if ( ! shape ) return null;
					return (
						<button
							key={ key }
							type="button"
							className={ `customize-control-responsive-buttonpreset__button${ selected === key ? ' is-active' : '' }` }
							onClick={ () => applyPreset( key ) }
							aria-label={ choices[ key ].label }
						>
							<svg width="89" height="35" viewBox="0 0 89 35" fill="none" xmlns="http://www.w3.org/2000/svg">
								{ shape.filled
									? <rect width="89" height="35" rx={ shape.rx } fill="currentColor" />
									: <rect x="0.5" y="0.5" width="88" height="34" rx={ shape.rx } stroke="currentColor" />
								}
								<path d={ BUTTON_TEXT_PATH } fill={ shape.filled ? '#ffffff' : 'currentColor' } />
							</svg>
						</button>
					);
				} ) }
			</div>
		</>
	);
};

ButtonPresetComponent.propTypes = {
	control: PropTypes.object.isRequired,
};

export default React.memo( ButtonPresetComponent );
